refentry.refsect1:
&reftitle.parameters;
&mysqli.link.description;
string
A string a ser colocada entre aspas e escapada.
Os caracteres codificados são NUL (ASCII 0), \n, \r, \, ', " e CTRLZ. Se o modo SQL NO_BACKSLASH_ESCAPES estiver habilitado na conexão, apenas ' será codificado, duplicando-o.

  &reftitle.examples;

   Exemplo de mysqli::quote_string
   &style.oop;


<?php

mysqli_report(MYSQLI_REPORT_ERROR | MYSQLI_REPORT_STRICT);
$mysqli = new mysqli("localhost", "my_user", "my_password", "world");

$city = "'s-Hertogenbosch";

/* esta consulta com $city entre aspas funcionará */
$query = sprintf("SELECT CountryCode FROM City WHERE name=%s", $mysqli->quote_string($city));
$result = $mysqli->query($query);
printf("Select returned %d rows.\n", $result->num_rows);

/* esta consulta falhará, pois não colocamos $city entre aspas nem a escapamos */
$query = sprintf("SELECT CountryCode FROM City WHERE name='%s'", $city);
$result = $mysqli->query($query);


   &style.procedural;


<?php

mysqli_report(MYSQLI_REPORT_ERROR | MYSQLI_REPORT_STRICT);
$mysqli = mysqli_connect("localhost", "my_user", "my_password", "world");

$city = "'s-Hertogenbosch";

/* esta consulta com $city entre aspas funcionará */
$query = sprintf("SELECT CountryCode FROM City WHERE name=%s", mysqli_quote_string($mysqli, $city));
$result = mysqli_query($mysqli, $query);
printf("Select returned %d rows.\n", mysqli_num_rows($result));

/* esta consulta falhará, pois não colocamos $city entre aspas nem a escapamos */
$query = sprintf("SELECT CountryCode FROM City WHERE name='%s'", $city);
$result = mysqli_query($mysqli, $query);


   &examples.outputs.similar;


